# Create test data for Phase 0 platform validation
# This script creates a sample .thing file and test image for platform testing

param(
    [string]$OutputDir = "test_data"
)

Write-Host "`n=== Creating Phase 0 Test Data ===" -ForegroundColor Cyan

# Create output directory
New-Item -ItemType Directory -Force -Path $OutputDir | Out-Null

# Create a simple test .thing file (mock FlatBuffers data)
# In production, this would be generated by the compiler
$thingData = @"
MOCK_THING_FILE_V1
{
  "hash": "test_hash_12345",
  "product": {
    "title": "Test Product",
    "price": 2999,
    "currency": "USD"
  }
}
"@

$thingPath = Join-Path $OutputDir "test.thing"
$thingData | Out-File -FilePath $thingPath -Encoding UTF8
Write-Host "✓ Created test .thing file: $thingPath" -ForegroundColor Green

# Instructions for test image
Write-Host "`n⚠️  Test Image Required" -ForegroundColor Yellow
Write-Host "Please provide a test image (JPEG or PNG) for embedding." -ForegroundColor White
Write-Host "`nNext steps:" -ForegroundColor Cyan
Write-Host "  1. Place a test image in: $OutputDir\test.jpg (or test.png)" -ForegroundColor White
Write-Host "  2. Run: cd packages\matter-core" -ForegroundColor White
Write-Host "  3. Run: cargo run --bin platform-test -- create-test-images ..\..\$OutputDir\test.jpg ..\..\$OutputDir\test.thing ..\..\$OutputDir\polyglots" -ForegroundColor White
Write-Host "`nThis will create polyglot images ready for platform testing.`n" -ForegroundColor Cyan
